package dev.eigenworks.client.screen;
import dev.eigenworks.computer.accelerator.AdvancedConsoleMenu;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
public final class AdvancedConsoleScreen extends AbstractContainerScreen<AdvancedConsoleMenu>{public AdvancedConsoleScreen(AdvancedConsoleMenu m,Inventory i,Component t){super(m,i,t,300,190);titleLabelX=10;titleLabelY=8;}@Override protected void init(){super.init();String[] s={"Module","Run","Bitrate","Latency","IK damping"};for(int i=0;i<5;i++)addRenderableWidget(b(s[i],leftPos+12+i*55,topPos+130,52,i));}private Button b(String s,int x,int y,int w,int id){return Button.builder(Component.literal(s),q->{if(minecraft!=null&&minecraft.gameMode!=null)minecraft.gameMode.handleInventoryButtonClick(menu.containerId,id);}).bounds(x,y,w,20).build();}@Override public void extractBackground(GuiGraphicsExtractor g,int x,int y,float p){g.fill(leftPos,topPos,leftPos+300,topPos+190,0xF00B1117);g.outline(leftPos,topPos,300,190,0xFF4DB6AC);}@Override protected void extractLabels(GuiGraphicsExtractor g,int x,int y){g.text(font,title,10,8,0xFF76E5D8,false);g.text(font,"Module index: "+menu.module(),15,35,0xFFE5E9F0,false);g.text(font,"CAN bitrate: "+menu.bitrate()/1000+" kbit/s",15,55,0xFFB4E1DC,false);g.text(font,"Network latency: "+menu.latencyMs()+" ms",15,75,0xFFB4E1DC,false);g.text(font,"IK damping: %.3f".formatted(menu.damping()),15,95,0xFFB4E1DC,false);g.text(font,"Last work: "+menu.cycles()+"   "+(menu.successful()?"OK":"FAULT"),15,112,menu.successful()?0xFF72E572:0xFFFF6868,false);}}
